package smartcampus;
import java.awt.*;import java.sql.*;
public class Users extends Panel{TextField name=UI.field(""),username=UI.field(""),email=UI.field("");TextArea out=new TextArea();Users(Frame f){setLayout(new BorderLayout(8,8));setBackground(UI.BG);add(UI.label("USER MANAGEMENT — CRUD",22,UI.NAVY),BorderLayout.NORTH);Panel p=new Panel(new GridLayout(0,2,5,5));p.add(new Label("Full Name"));p.add(name);p.add(new Label("Username"));p.add(username);p.add(new Label("Email"));p.add(email);Button add=UI.button("ADD USER",UI.GREEN),del=UI.button("DELETE BY USERNAME",UI.RED),load=UI.button("REFRESH LIST",UI.CYAN);p.add(add);p.add(del);p.add(load);add(p,BorderLayout.WEST);out.setEditable(false);add(out,BorderLayout.CENTER);add.addActionListener(e->add());del.addActionListener(e->del());load.addActionListener(e->load());load();}void add(){try(Connection c=DB.get();PreparedStatement p=c.prepareStatement("insert into users(full_name,username,password_hash,email,role,status) values(?,?,?,?,'Staff','Active')")){p.setString(1,name.getText());p.setString(2,username.getText());p.setString(3,"welcome123");p.setString(4,email.getText());p.executeUpdate();load();}catch(Exception e){out.setText(e.getMessage());}}void del(){try(Connection c=DB.get();PreparedStatement p=c.prepareStatement("delete from users where username=?")){p.setString(1,username.getText());p.executeUpdate();load();}catch(Exception e){out.setText(e.getMessage());}}void load(){try(Connection c=DB.get()){ResultSet r=c.createStatement().executeQuery("select user_id,full_name,username,email,role,status from users order by user_id");StringBuilder s=new StringBuilder("ID | NAME | USERNAME | EMAIL | ROLE | STATUS\n");while(r.next())s.append(r.getInt(1)).append(" | ").append(r.getString(2)).append(" | ").append(r.getString(3)).append(" | ").append(r.getString(4)).append(" | ").append(r.getString(5)).append(" | ").append(r.getString(6)).append('\n');out.setText(s.toString());}catch(Exception e){out.setText("DB error: "+e.getMessage());}}}
